import { Settings } from '../../shared/settings/Settings.js';
import { Logger } from '../../shared/utils/Logger.js';
import { startPlayerAudioVisualizer, initPlayerAudio, suspendPlayerAudioContext, stopPlayerQueuedAudio, closePlayerAudioBufferIterator, closePlayerAudioBufferIteratorSoon, runPlayerAudioIterator, syncPlayerVolume } from '../audio/AudioEngine.js';
import { startPlayerRenderLoop } from './RenderLoop.js';
import { savePlayerPlaybackState } from './PlaybackState.js';
import { getPlayerPlaybackTime } from './PlaybackState.js';
import { startPlayerVideoIterator } from './VideoIterator.js';

/** When each player last paused (performance.now()), to spot a long pause. @type {WeakMap<object, number>} */
const pausedAtWall = new WeakMap();

export async function playPlayer(player) {
    player.stream.onPlay();

    const streamHandled = await player.stream.playStream();
    if (streamHandled) return;

    player.announce.volume();

    if (player.isPlaying) return;
    if (!player.videoTrack && !player.audioTrack) return;

    Logger.log(`[Play] Starting playback - isAudioMode: ${player.isAudioMode}, playbackTimeAtStart: ${player.playbackTimeAtStart}`);

    try {
        initPlayerAudio(player);

        if (player.audioContext && player.audioContext.state === 'suspended') {
            const resumePromise = player.audioContext.resume();
            const timeoutPromise = new Promise((_, reject) =>
                setTimeout(() => reject(new Error('AudioContext resume timed out')), 3000)
            );
            await Promise.race([resumePromise, timeoutPromise]);
        }
    } catch (e) {
        Logger.warn('[Play] AudioContext blocked/failed:', e);
        Logger.log('[Play] Auto-muting due to audio block...');
        player.stream.wasMutedForAutoplay = true;
        if (!player.config.muted) {
            player.config.muted = true;
            syncPlayerVolume(player);
            if (player.ui.muteBtn) player.announce.volume();
        }
    }

    player.isPlaying = true;
    player.announce.playState();

    if (player.isLive) {
        let forceRestart = false;
        Logger.log(`[Play:Live] isLive=${player.isLive}, videoTrack=${!!player.videoTrack}, audioContext=${!!player.audioContext}, audioCtxTime=${player.audioContext?.currentTime?.toFixed(3)}`);
        
        const lastPosition = getPlayerPlaybackTime(player);
        const isLastPosUnix = lastPosition > 1000000000;
        const isStartTsUnix = (player.stream?.liveStartTimestamp || 0) > 1000000000;

        if (lastPosition > 0 && isLastPosUnix === isStartTsUnix && Math.abs(lastPosition - (player.stream?.liveStartTimestamp || 0)) > 1.0) {
            player.stream.liveStartTimestamp = lastPosition;
            Logger.log(`[Play:Live] Resuming from last position: ${player.stream?.liveStartTimestamp.toFixed(3)}`);
        }

        if (player.isLive && player.stream?.liveStartTimestamp) {
            const currentLiveEdge = await player.videoTrack.getDurationFromMetadata({ skipLiveWait: true });
            const drift = (currentLiveEdge ?? 0) - player.stream?.liveStartTimestamp;
            // If drift is too large (lagging or leading), reset to edge
            if (Math.abs(drift) > 60) {
                Logger.log(`[Play:Live] Resume position drift is too high (${drift.toFixed(1)}s) — resetting to edge`);
                player.stream.liveStartTimestamp = null;
                forceRestart = true;
            }
        }

        if (!player.stream?.liveStartTimestamp || forceRestart) {
            if (player.videoTrack) {
                try {
                    const currentLiveEdge = await player.videoTrack.getDurationFromMetadata({ skipLiveWait: true });
                    const refreshInterval = await player.videoTrack.getLiveRefreshInterval();
                    const backoff = (refreshInterval || 6) * 3;
                    player.stream.liveStartTimestamp = Math.max(0, (currentLiveEdge ?? 0) - backoff);
                    Logger.log(`[Play:Live] Calculated new live start: ${player.stream?.liveStartTimestamp.toFixed(3)}`);
                } catch (e) {
                    player.stream.liveStartTimestamp = Date.now() / 1000 - 15;
                }
            } else {
                player.stream.liveStartTimestamp = Date.now() / 1000 - 15;
            }
        } else {
            Logger.log(`[Play:Live] Using existing live start timestamp: ${player.stream?.liveStartTimestamp.toFixed(3)}`);
        }
        
        await player.stream?.startLiveVideoLoop(forceRestart);
        player.announce.streamState();
        return; // IMPORTANT: Prevent VOD logic below from clobbering the live loop
    }

    // After a long pause the browser may reclaim the video decoder, wedging the
    // old iterator: its pending next() never resolves, so video freezes while
    // audio (restarted on every play) keeps going. Drop the stale iterator
    // WITHOUT awaiting return() — a wedged async generator queues return()
    // behind the stuck next(), which would hang this whole play() call — and
    // let the restart below spin up a fresh decoder at the same position.
    const pausedAt = pausedAtWall.get(player);
    const pausedForSec = pausedAt ? (performance.now() - pausedAt) / 1000 : 0;
    if (pausedForSec > 10 && player.frames.isOpen && !player.isLive) {
        Logger.log(`[Play] Resuming after ${pausedForSec.toFixed(0)}s pause — restarting video iterator (decoder may be reclaimed)`);
        player.frames.abandon();
    }
    pausedAtWall.delete(player);

    // Anchored before anything asks the clock, not after.
    //
    // When no audio anchor exists, position is measured as the time elapsed
    // since fallbackStartTime plus playbackTimeAtStart. Left over from an
    // earlier play, that origin reports a position with no relation to where
    // playback actually is -- and this used to be set below, after both the
    // check and the rebuild had already read it.
    //
    // What that cost: on loop-one, completeMedia seeks to 0 and calls play(),
    // the stale clock reported about 2s on a 2s file, so the reset branch fired
    // although playback was already at the start, and _startVideoIterator
    // opened an iterator past the end of the file. It yielded a frame or two,
    // the pump saw `done` and dropped it, and nothing reopened it -- the render
    // loop only pumps while the queue is open. The clock went on looping and
    // isPlaying stayed true, so the player looked healthy while drawing fell
    // from about 15fps to about 1fps. Pressing play after a video had ended
    // froze the picture the same way, for the same reason.
    player.fallbackStartTime = performance.now();

    const currentPosition = getPlayerPlaybackTime(player);
    if (player.duration > 1.0 && currentPosition >= player.duration - 0.5) {
        Logger.log(`[Play] Resetting to start (position=${currentPosition.toFixed(2)}, duration=${player.duration.toFixed(2)})`);
        player.playbackTimeAtStart = 0;
        // Both clocks move with the position, or the next reader disagrees.
        //
        // The anchor is the one that matters here and was the harder half to
        // see. getPlayerPlaybackTime prefers it whenever the AudioContext is
        // running, and play() resumes the context a few lines above -- so an
        // anchor left over from the finished playthrough (content near the
        // duration) reported a position past the end, the iterator was opened
        // there, and it was exhausted on arrival. seekPlayerTo already clears
        // it when repositioning; this branch is a reposition that did not.
        player.fallbackStartTime = performance.now();
        player.vodAnchor.clear();
        await startPlayerVideoIterator(player);
    } else if (!player.frames.isOpen) {
        await startPlayerVideoIterator(player);
    }

    if (player.audioSink) {
        if (!player.isLive) {
            const startTime = player.playbackTimeAtStart;
            await closePlayerAudioBufferIterator(player);
            Logger.log(`[Play] Starting audio iterator at time: ${startTime.toFixed(2)}s`);
            const audioIterator = player.audioBuffers.open(player.audioSink, startTime);

            const firstResult = await audioIterator.next();
            const vodPrefetchedBuffer = firstResult?.value ?? null;

            const vodAnchorWall = player.audioContext.currentTime + 0.02;
            const vodAnchorContent = vodPrefetchedBuffer?.timestamp ?? startTime;
            player.vodAnchor.set(vodAnchorWall, vodAnchorContent);
            Logger.log(`[Play] VOD anchor prefetched — wall=${vodAnchorWall.toFixed(3)}, content=${vodAnchorContent.toFixed(3)}, buffer=${vodPrefetchedBuffer ? 'ok' : 'null'}`);

            runPlayerAudioIterator(player, audioIterator, vodAnchorWall, vodAnchorContent, vodPrefetchedBuffer);
        }

        await startPlayerAudioVisualizer(player);
    }

    startPlayerRenderLoop(player);

    if (player.controlBarMode === 'overlay') {
        setTimeout(() => {
            if (player.isPlaying && player.controlBarMode === 'overlay') {
                player.controlBar?.startAutoHideTimer();
            }
        }, 500);
    }

    if (player.ui.playOverlay) {
        player.ui.playOverlay.style.display = 'none';
    }
}

export function pausePlayer(player, showOverlay = true) {
    Logger.log('Player.pause() called');

    player.stream.onPause();

    const streamHandled = player.stream.pauseStream(showOverlay);
    if (streamHandled) return;

    const calculatedTime = getPlayerPlaybackTime(player);

    if (calculatedTime < 0.1 && player.currentTime > 1.0) {
        Logger.warn(`[Pause] Correction: the playback clock returned ${calculatedTime} but currentTime is ${player.currentTime}. Keeping ${player.currentTime}.`);
        player.playbackTimeAtStart = player.currentTime;
    } else {
        player.playbackTimeAtStart = calculatedTime;
    }
    player.isPlaying = false;
    pausedAtWall.set(player, performance.now());
    player.controlBar?.clearAutoHideTimer();

    player.announce.playState();

    closePlayerAudioBufferIteratorSoon(player);

    if (player.animationFrameId) {
        cancelAnimationFrame(player.animationFrameId);
        player.animationFrameId = null;
    }

    suspendPlayerAudioContext(player);

    stopPlayerQueuedAudio(player);

    savePlayerPlaybackState(player);

    if (player.ui.playOverlay && !player.isLoading) {
        const shouldShow = showOverlay && player.config.controls.playOverlay;
        player.ui.playOverlay.style.display = shouldShow ? 'flex' : 'none';
    }

    if (player.isAudioMode && player.audioVisualizer) {
        player.audioVisualizer.stop();
    }
}

export async function setPlayerPlaybackRate(player, rate, { persist = true } = {}) {
    if (rate < 0.25 || rate > 2) return;
    if (player.isLive) {
        if (player.playbackRate !== 1) {
            player.playbackRate = 1;
        }
        player.announce.rate();
        return;
    }

    const wasPlaying = player.isPlaying;
    const currentPosition = getPlayerPlaybackTime(player);

    if (wasPlaying) {
        player.pause();
        await player.audioBuffers.settle();
    }

    player.playbackRate = rate;
    if (persist) Settings.set('speed', rate);
    player.announce.rate();

    if (wasPlaying) {
        await player.seek(currentPosition);
        await player.play();
    }
}
